<?php
namespace Opencart\Catalog\Controller\Extension\Noveraile\Page;
class Terms extends \Opencart\System\Engine\Controller { public function index(): void { $this->load->language('extension/noveraile/module/noveraile');$this->document->setTitle($this->language->get('six_terms_title'));$data=$this->language->all();$data['page_title']=$this->language->get('six_terms_title');$data['page_copy']='<h2>Orders and payment</h2><p>An order is accepted after payment confirmation. Product availability and made-to-order lead times are shown before checkout.</p><h2 id="returns">Returns and exchanges</h2><p>Contact the atelier before returning an item. Engraved, resized or otherwise personalised pieces may not be returnable except where required by law.</p><h2 id="warranty">Warranty</h2><p>Manufacturing defects are assessed by our atelier. Normal wear, accidental damage and third-party repairs are excluded.</p>'; $data['header']=$this->load->controller('common/header');$data['footer']=$this->load->controller('common/footer');$this->response->setOutput($this->load->view('extension/noveraile/page/legal',$data)); } }
